window.kbPageData["views/entry/k-dba2f598313639fa"] = {"key":"entry/k-dba2f598313639fa","state":{"route":"entry/k-dba2f598313639fa"},"node":{"id":"k-dba2f598313639fa","mode":"k","title":"分步乘法计数原理","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2023 副省级 行测#68","国考 2023 行政执法 行测#67","国考 2024 行政执法 行测#70","江苏 2023 A类 行测#60","江苏 2023 B类 行测#60","江苏 2024 A类 行测#62","江苏 2024 C类 行测#62","江苏 2025 A类 行测#64","江苏 2025 B类 行测#64","江苏 2025 C类 行测#64"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":4,"reviewSet":"多题条目","independentCount":6,"directorySummary":"若每个结果恰好对应一条完整的选择路径，且无论此前怎样选择，第i步都有nᵢ种选法，那么结果总数为n₁×n₂×…×nₖ，其中k为步骤数。","review":{"title":"分步乘法计数原理","type":"原理与机制","definition":"若每个结果恰好对应一条完整的选择路径，且无论此前怎样选择，第i步都有nᵢ种选法，那么结果总数为n₁×n₂×…×nₖ，其中k为步骤数。","explanation":"前面的选择可以改变后续的可选对象，只要各步的可选数量保持固定，就可以直接相乘。若后续选法数随前面的选择而变，可以按前面的选择划分互不重叠的情形，在各情形内分别计数，再将结果相加。","basis":"据关联原题及所列出处编释。","references":[{"source":"count","location":"13.5 计数原理"}],"related":["k-e9c35702da80f9b6","k-63c2d85fb3976c99"],"examFocus":{"国考 2023 副省级 行测#68":"用满租条件确定各类租户占用的铺位，再分步计算店铺顺序和租户安排。","江苏 2025 A类 行测#64":"首尾节目单独安排，分开核对相邻节目组的内部顺序与小品、魔术的间隔限制。","国考 2023 行政执法 行测#67":"按三个时段分别选人和排序，核对每次安排会怎样限制后续时段的同校学者。","国考 2024 行政执法 行测#70":"先处理甲地对批次的限制，再按其余两地均须接待的条件分配剩余批次。","江苏 2024 A类 行测#62":"先按不同级别城市的派员要求确定人数，再分步统计不同专员的去向。","江苏 2023 A类 行测#60":"按首日限制和相邻两天的展品关系逐日计数，再检查哪些安排遗漏了某类文物。"}},"aspects":[{"title":"相邻限制下的排序","uses":[{"unit":"Q1","role":"解题依据","use":"铺位全部租出时，恰有一家餐厅占用相邻两铺。将它视为一个租户位置，同类租户间隔要求使餐厅和水果店只能交替排列。占双铺的餐厅、交替顺序、餐厅次序和水果店次序各有2种选择，共16种，对应D项。（国考 2023 副省级 行测第68题）","evidence":"且相同类型的两个租户之间至少要间隔1个铺位","qids":["国考 2023 副省级 行测#68"]},{"unit":"Q6","role":"解题依据","use":"两首歌分占首尾有2种排法，相邻的舞蹈和杂技有2种内部次序，小品和魔术分居相邻节目组两侧有2种排法。三步相乘得8种，对应A项。（江苏 2025 A类 行测第64题、江苏 2025 B类 行测第64题、江苏 2025 C类 行测第64题）","evidence":"2×2×2=8种节目演出的排列顺序。","qids":["江苏 2025 A类 行测#64","江苏 2025 B类 行测#64","江苏 2025 C类 行测#64"]}]},{"title":"分时段选人并排序","uses":[{"unit":"Q2","role":"解题依据","use":"上午从3所高校各选1人并排序，有192种排法。下午必须安排上午未出现高校的1人，否则该校两人都会留到晚上。再从上午出现的3所高校中选出2所，各安排剩下的1人，与下午已选的学者一起排序，有36种排法。晚上剩下的两人来自不同高校，有2种排法。三段相乘得13824种，对应C项。（国考 2023 行政执法 行测第67题）","evidence":"则这8人的报告次序共有192×36×2=13824种不同的安排方式，在C项范围内。","qids":["国考 2023 行政执法 行测#67"]}]},{"title":"按目的地分步分配","uses":[{"unit":"Q3","role":"解题依据","use":"第一、二批不能去甲地。选定后面哪些批次去甲地后，再把其余批次分到乙、丙，且两地各至少一批。甲地接待1、2、3批时，两步分别相乘得42、18、2种，再合计为62种，对应B项。（国考 2024 行政执法 行测第70题）","evidence":"每个地方至少安排一批。受接待能力影响，第一、二批不去甲地","qids":["国考 2024 行政执法 行测#70"]},{"unit":"Q5","role":"解题依据","use":"两个二线城市各派1人，两个一线城市因此分别派2人和1人。确定一线城市的人员安排有60种，每种安排下剩下两人分到两个二线城市均有2种排法，相乘得120种，对应C项。（江苏 2024 A类 行测第62题、江苏 2024 C类 行测第62题）","evidence":"分步用乘法，则不同的派出方法共有60×2=120种。","qids":["江苏 2024 A类 行测#62","江苏 2024 C类 行测#62"]}]},{"title":"逐日计数并扣除漏展","uses":[{"unit":"Q4","role":"解题依据","use":"先暂缓执行五类文物都要展出的要求。首日从青铜器、瓷器、书法中选两类，此后每天从前一天未展出的三类中选两类，每天均有3种选法，共81种。再扣除9种漏展方案，得72种，对应A项。（江苏 2023 A类 行测第60题、江苏 2023 B类 行测第60题）","evidence":"故满足条件的情况数=总情况数-不满足条件的情况数=81-6-3=72种。","qids":["江苏 2023 A类 行测#60","江苏 2023 B类 行测#60"]}]}]},"questions":{"国考 2023 副省级 行测#68":{"paper":"国考 2023 副省级 行测","n":68,"mod":"数量关系","src":["503793642e845de9795f.pdf",12],"asrc":["ecade1ff5af69283232e.pdf",21],"card":"6bd03d5441e0d0210fea4ca0","links":[{"id":"k-dba2f598313639fa","role":"解题依据","why":"每个可行安排由占双铺的餐厅、租户类型顺序和同类租户次序共同确定，各步的选法数相乘。"}]},"国考 2023 行政执法 行测#67":{"paper":"国考 2023 行政执法 行测","n":67,"mod":"数量关系","src":["857378cf496f27296500.pdf",11],"asrc":["d23139fe5a0fb3115135.pdf",21],"card":"330e820036515a91ed2ad96c","links":[{"id":"k-dba2f598313639fa","role":"解题依据","why":"以各阶段合法选人与排序的方式数相乘，得到完整报告次序的数量。"}]},"国考 2024 行政执法 行测#70":{"paper":"国考 2024 行政执法 行测","n":70,"mod":"数量关系","src":["dfddc59dc6e7d9da5d71.pdf",13],"asrc":["6493f3a6a55c38431852.pdf",22],"card":"be6819af79813afbc178f31c","links":[{"id":"k-dba2f598313639fa","role":"解题依据","why":"对每种已选定的甲地批次，剩余批次在乙、丙两地的分配数相同，因此两步的方式数相乘。"}]},"江苏 2023 A类 行测#60":{"paper":"江苏 2023 A类 行测","n":60,"mod":"数量关系","src":["22304fe4c340e19d7902.pdf",11],"asrc":["be17f9afe070cf13a0fb.pdf",17],"card":"9479a58ec9bdb0fae03bb9ad","links":[{"id":"k-dba2f598313639fa","role":"解题依据","why":"逐日选定展品时，下一天只能从前一天未展出的类别中选取，可将各步的选择数相乘。"}]},"江苏 2023 B类 行测#60":{"paper":"江苏 2023 B类 行测","n":60,"mod":"数量关系","src":["22262c34d18cd68fbee4.pdf",10],"asrc":["b08f2713d73015eac675.pdf",19],"card":"4864c96e7939a1f7e4cb158c","links":[{"id":"k-dba2f598313639fa","role":"解题依据","why":"暂放宽各类均须展出的条件后，每天可按前一天选出的类别确定当日选择数，再将各步选择数相乘。"}]},"江苏 2024 A类 行测#62":{"paper":"江苏 2024 A类 行测","n":62,"mod":"数量关系","src":["f8fec75f67d6d1ba5759.pdf",11],"asrc":["0126a1c8aceee632ea2b.pdf",18],"card":"3125fb2194e994fd1c46cff3","links":[{"id":"k-dba2f598313639fa","role":"解题依据","why":"一线城市和二线城市的派员安排构成一次完整分配的两个步骤，需将各步方案数相乘。"}]},"江苏 2024 C类 行测#62":{"paper":"江苏 2024 C类 行测","n":62,"mod":"数量关系","src":["3f1ec77ae8a18519b57e.pdf",11],"asrc":["02d6b49839583bdaf297.pdf",17],"card":"4f1115f40753da3857970846","links":[{"id":"k-dba2f598313639fa","role":"解题依据","why":"每个一线城市派员方案都可搭配相同数量的二线城市派员方案，故将两步的方案数相乘。"}]},"江苏 2025 A类 行测#64":{"paper":"江苏 2025 A类 行测","n":64,"mod":"数量关系","src":["98687766ac277f427cd6.pdf",13],"asrc":["4fe8e0544dd7b47699d2.pdf",20],"card":"a5689593421c82c94e0ded40","links":[{"id":"k-dba2f598313639fa","role":"解题依据","why":"当每一步的可选数固定，且各步选择共同确定一种完整排法时，总数等于各步可选数之积。"}]},"江苏 2025 B类 行测#64":{"paper":"江苏 2025 B类 行测","n":64,"mod":"数量关系","src":["91e0d9fd02ca7ec6d61f.pdf",12],"asrc":["f2ff67a0f2a2f7e8e926.pdf",21],"card":"1adf49e0fd4d623a742c02e8","links":[{"id":"k-dba2f598313639fa","role":"解题依据","why":"各步的可选安排数确定后，将其相乘得到完整排列的数量。"}]},"江苏 2025 C类 行测#64":{"paper":"江苏 2025 C类 行测","n":64,"mod":"数量关系","src":["ffc394a1c160f331ec57.pdf",14],"asrc":["d1de3b437151c05b769e.pdf",19],"card":"a35415b0ca26a09f9c5c7bce","links":[{"id":"k-dba2f598313639fa","role":"解题依据","why":"首尾歌曲安排、相邻节目内部排序和空位安排依次完成，各步计数相乘得到总排列数。"}]}},"terms":{"k-e9c35702da80f9b6":{"id":"k-e9c35702da80f9b6","mode":"k","type":"原理与机制","title":"分类加法计数原理","qs":[],"count":3},"k-63c2d85fb3976c99":{"id":"k-63c2d85fb3976c99","mode":"k","type":"原理与机制","title":"分类加法与分步乘法计数原理","qs":[],"count":2}},"references":{"count":{"name":"OpenStax《Algebra and Trigonometry 2e》计数原理","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/13-5-counting-principles"}},"topics":[],"units":{"k-dba2f598313639fa":[["国考 2023 副省级 行测#68"],["国考 2023 行政执法 行测#67"],["国考 2024 行政执法 行测#70"],["江苏 2023 A类 行测#60","江苏 2023 B类 行测#60"],["江苏 2024 A类 行测#62","江苏 2024 C类 行测#62"],["江苏 2025 A类 行测#64","江苏 2025 B类 行测#64","江苏 2025 C类 行测#64"]]}};
